// Source: IntentUI - https://design.intentui.com/blocks (stats-02)
// Installed via: npx shadcn@latest add @irsyad/stats-02

import { Container } from "@/registry/ui/container";
import type { Stats_2_Block } from "~/payload-types";

export default function Stats2(props: Stats_2_Block) {
	return (
		<div className="py-6 sm:py-12">
			<Container>
				<div className="xl:grid xl:grid-flow-col-dense xl:gap-x-8">
					<div className="relative">
						<div className="max-w-3xl">
							{props.eyebrow && (
								<h2 className="font-semibold text-base text-primary-subtle-fg">
									{props.eyebrow}
								</h2>
							)}
							<p className="mt-2 text-pretty font-bold text-3xl text-fg tracking-tight">
								{props.header}
							</p>
							<p className="mt-2 text-lg text-muted-fg">{props.subheader}</p>
						</div>
						<div className="mt-12 grid grid-cols-1 gap-x-6 gap-y-6 sm:grid-cols-3">
							{props.stats?.map((item, index) => (
								<div
									className="rounded-lg border border-muted-fg/20 p-6 ring ring-muted-fg/30 ring-offset-4 ring-offset-muted"
									key={index}
								>
									<span className="block font-semibold text-3xl text-fg">{item.stat}</span>
									<span className="mt-2 block text-base/6 text-muted-fg">
										<strong className="font-medium text-fg">{item.emphasis}</strong>{" "}
										{item.description}
									</span>
								</div>
							))}
						</div>
					</div>
				</div>
			</Container>
		</div>
	);
}

import type { Block } from "payload";

import {
	BLOCK_GROUP_STATS,
	BLOCK_SLUG_STATS_2,
} from "@/registry/default/lib/constants/blocks";
import headerField from "@/registry/default/lib/fields/header/config";
import subHeaderField from "@/registry/default/lib/fields/subheader/config";

export const Stats_2_Block: Block = {
	slug: BLOCK_SLUG_STATS_2,
	admin: {
		group: BLOCK_GROUP_STATS,
	},
	fields: [
		{
			type: "collapsible",
			label: "Content",
			admin: {
				initCollapsed: false,
			},
			fields: [
				{
					name: "eyebrow",
					type: "text",
					label: "Eyebrow Text",
					admin: {
						description: "Small label above the main heading (optional)",
					},
					defaultValue: "Results",
				},
				headerField({
					defaultValue: "Built for scale, proven in production",
				}),
				subHeaderField({
					defaultValue:
						"Faster onboarding, higher reliability, and happier teams backed by real usage and measurable outcomes.",
				}),
			],
		},
		{
			type: "collapsible",
			label: "Statistics",
			admin: {
				initCollapsed: false,
			},
			fields: [
				{
					name: "stats",
					type: "array",
					label: "Statistics",
					required: true,
					minRows: 1,
					maxRows: 6,
					fields: [
						{
							name: "stat",
							type: "text",
							label: "Statistic Value",
							required: true,
							admin: {
								description: "Large numeric value (e.g., '14K+', '99.95%')",
							},
						},
						{
							name: "emphasis",
							type: "text",
							label: "Emphasized Text",
							required: true,
							admin: {
								description: "Bold descriptive text",
							},
						},
						{
							name: "description",
							type: "text",
							label: "Description",
							required: true,
							admin: {
								description: "Additional context text",
							},
						},
					],
					defaultValue: [
						{
							stat: "14K+",
							emphasis: "Teams onboarded",
							description: "switched from spreadsheets to automated workflows.",
						},
						{
							stat: "180M+",
							emphasis: "Monthly API calls",
							description: "served across five global regions.",
						},
						{
							stat: "99.95%",
							emphasis: "Uptime this year",
							description: "with multi region failover in production.",
						},
					],
				},
			],
		},
	],
	interfaceName: "Stats_2_Block",
	labels: {
		plural: "Stats 2's",
		singular: "Stats 2",
	},
};
